// Texture.h -- procedural textures and the on-screen HUD (IMPLEMENTATION_GUIDE.md §9.3, §9.4).
//
// No image files and no loader library: every texture is generated by code at
// startup (tileable value noise or a pattern formula, using hashNoise from
// MathUtils.h) and uploaded once with glTexImage2D. The HUD's bitmap font is a
// small texture too, drawn on screen-space quads.
#pragma once
#include <GL/glew.h>
#include <string>
#include <vector>
#include "MathUtils.h"

namespace Tex {

// Texture ids selectable per draw call (uTexId). Must match the numbers in basic.frag.
enum Id { None = 0, Rock = 1, Ash = 2, Wood = 3 };

struct Textures {
    GLuint rock = 0, ash = 0, wood = 0;

    // Generate and upload the three 256x256 modulation textures (mean value ~0.5,
    // so the shader multiplies the albedo by 2 * texel and the average stays 1).
    void build();

    // Bind rock / ash / wood to texture units 0 / 1 / 2.
    void bind() const;
};

} // namespace Tex

// Screen-space text and panels, batched into one draw call per frame.
class Hud {
public:
    bool init();                              // creates the shader, the font atlas and the buffers
    void begin(int screenW, int screenH);     // start a frame's batch
    void panel(float x, float y, float w, float h, float r, float g, float b, float a);
    // Draws upper-case text (lower case is folded to upper). `px` is the glyph height in pixels.
    void text(float x, float y, const std::string& s, float px, float r, float g, float b, float a = 1.0f);
    void flush();                             // draw the batch
    // Draw an RGB texture (the light-map minimap) as a screen-space quad, brightened by `gain`.
    void image(GLuint tex, float x, float y, float w, float h, float gain);

    static float textWidth(const std::string& s, float px);

private:
    GLuint program_ = 0, vao_ = 0, vbo_ = 0, font_ = 0;
    int w_ = 1280, h_ = 720;
    std::vector<float> verts_;                // x, y, u, v, r, g, b, a per vertex
    void quad(float x, float y, float w, float h, float u0, float v0, float u1, float v1,
              float r, float g, float b, float a);
};
